PORTS=('Ports of loading','Kakinada, Visakhapatnam, Chennai (other Indian ports on request)')
INCO=('Incoterms','FOB, CFR, CIF')
DOCS_R=('Documents','Commercial invoice, packing list, certificate of origin, phytosanitary certificate, fumigation certificate, third-party inspection (SGS or similar) on request')
DOCS_S=('Documents','Commercial invoice, packing list, certificate of origin, phytosanitary certificate, lab analysis report, third-party inspection on request')
BAS_PACK=[('Bag sizes','1 kg, 5 kg, 10 kg, 20 kg, 25 kg, 39 kg, 40 kg, 50 kg'),('Bag types','PP woven, BOPP printed, non-woven, jute'),('Private label','Available, with your brand artwork')]
NB_PACK=[('Bag sizes','25 kg, 50 kg (5 kg and 10 kg retail packs on request)'),('Bag types','PP woven, BOPP printed, jute'),('Private label','Available, with your brand artwork')]
def bship(): return [INCO,PORTS,('20 ft container','About 24 – 25 MT'),DOCS_R]
def nship(): return [INCO,PORTS,('20 ft container','About 26 – 27 MT'),DOCS_R]
def SAMPLE(): return ('Can I get a sample before ordering?','Yes. We can courier a sample of the exact lot for your approval before the contract is confirmed.')
def MOQ(n,mt): return (f'What is the minimum order for {n}?',f'Our standard minimum is one 20 ft container ({mt}). Smaller trial lots can be discussed for new buyers.')
def BRAND(): return ('Can you pack under our own brand?','Yes. We can print your brand on BOPP or non-woven bags in any of the standard sizes.')
STEAM_SELLA=lambda n:[(f'{n} Steam','Steam-processed for a firm, non-sticky cooked grain with a creamy white colour.'),
                      (f'{n} Golden Sella','Parboiled for a golden colour and strong grains that stay separate after cooking.'),
                      (f'{n} White Sella / Raw','White Sella (parboiled, white colour) or Raw (unprocessed) for a softer texture and fresher aroma.')]
def bspec(agl,cooked,purity='95% min',hs='1006 30 20'):
    return [('Average grain length (before cooking)',agl),('Average grain length (after cooking)',cooked),('Moisture','12 – 13% max'),('Broken grains','1 – 2% max'),
            ('Damaged / discoloured grains','1% max'),('Chalky grains','1 – 2% max'),('Purity (variety)',purity),('Foreign matter','Nil'),('Polish','Double polished, sortex cleaned'),('HS code',hs)]
def nspec(agl,extra=None,hs='1006 30 10 (parboiled) / 1006 30 90 (raw)'):
    r=[('Average grain length',agl),('Moisture','14% max'),('Broken grains','5% / 25% / 100% (as ordered)'),('Damaged / discoloured grains','1 – 2% max'),
       ('Chalky grains','5% max'),('Red / striped grains','2% max'),('Foreign matter','0.1% max'),('Polish','Double polished, sortex cleaned'),('HS code',hs)]
    return r+(extra or [])

