def sship(c20): return [INCO,('Ports of loading','Chennai, Visakhapatnam, Kakinada, Kochi, Mundra (depending on origin)'),('20 ft container',c20),DOCS_S]
def sfaq(n,moq,extra): return [(f'What is the minimum order for {n}?',moq),extra,('Do you provide a lab report?','Yes. Each lot can be shipped with a lab analysis report, and we can arrange testing to your market’s limits (for example EU pesticide residue limits) on request.'),SAMPLE()]
